arguments:
// Protocolites Renderer V4 - Animated SVG
// Expected global variables (set before this script runs):
// - tokenId: number
// - dna: string (hex)
// - isKid: boolean
// - parentDna: string (hex)
// - size: number (16 or 24)

// Hash function for seeding
function hashCode(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h &= h;
  }
  return Math.abs(h);
}

// Family color definitions
const families = {
  red: "#cc0000",
  green: "#008800",
  blue: "#0044cc",
  yellow: "#cc9900",
  purple: "#8800cc",
  cyan: "#0088aa"
};

// Determine family from DNA
function getFamilyFromDNA(d) {
  const b = BigInt(d);
  const f = b >> 17n;
  const h = Number(f % 16777216n);
  const k = Object.keys(families);
  return k[h % k.length];
}

const family = getFamilyFromDNA(dna);
const familyColor = families[family];

// Seeded random number generator
let seed = hashCode(dna);
function random() {
  seed = (seed * 9301 + 49297) % 233280;
  return seed / 233280;
}

// DNA Decoding
function decodeDNA(d) {
  const n = BigInt(d);
  const bt = ["square", "round", "diamond", "mushroom", "invader", "ghost"];
  const bc = ["\u2588", "\u2593", "\u2592", "\u2591"];
  const ec = ["\u25cf", "\u25c9", "\u25ce", "\u25cb"];
  const at = ["\u25cf", "\u25c9", "\u25cb", "\u25ce", "\u2726", "\u2727", "\u2605"];
  const ht = ["none", "top", "flat", "double", "fancy"];

  return {
    bodyType: bt[Number((n >> 0n) & 7n) % 6],
    bodyChar: bc[Number((n >> 3n) & 3n)],
    eyeChar: ec[Number((n >> 5n) & 3n)],
    eyeSize: Number((n >> 7n) & 1n) === 1 ? "mega" : "normal",
    antennaTip: at[Number((n >> 8n) & 7n) % 7],
    armStyle: Number((n >> 11n) & 1n) === 1 ? "line" : "block",
    legStyle: Number((n >> 12n) & 1n) === 1 ? "line" : "block",
    hatType: ht[Number((n >> 13n) & 7n) % 5],
    hasCigarette: Number((n >> 16n) & 1n) === 1
  };
}

const dnaObj = decodeDNA(dna);

// Initialize grid
const grid = Array(size).fill().map(() =>
  Array(size).fill(null).map(() => ({ char: " ", type: "empty" }))
);

const cx = Math.floor(size / 2);
const cy = Math.floor(size / 2);
const bodyType = dnaObj.bodyType;
const bodyWidth = size === 24 ? 6 : 3;
const bodyHeight = size === 24 ? 8 : 4;
const bodyStartY = size === 24 ? 7 : 6;

// Draw body
for (let y = 0; y < bodyHeight; y++) {
  for (let x = -bodyWidth; x <= bodyWidth; x++) {
    const posY = bodyStartY + y;
    const posX = cx + x;
    let inBody = false;
    const relX = x / bodyWidth;
    const relY = (y - bodyHeight / 2) / (bodyHeight / 2);

    if (bodyType === "square") {
      inBody = true;
    } else if (bodyType === "round") {
      const dist = Math.sqrt(relX * relX + relY * relY);
      inBody = dist <= 1.0;
    } else if (bodyType === "diamond") {
      inBody = Math.abs(relX) + Math.abs(relY) <= 1.0;
    } else if (bodyType === "mushroom") {
      if (isKid) {
        if (relY < -0.2) {
          inBody = true;
        } else {
          inBody = Math.abs(relX) <= 0.7;
        }
      } else {
        if (relY < 0) {
          inBody = true;
        } else {
          inBody = Math.abs(relX) <= 0.6;
        }
      }
    } else if (bodyType === "invader") {
      if (relY < -0.3) {
        inBody = Math.abs(relX) <= 0.7;
      } else if (relY < 0.3) {
        inBody = true;
      } else {
        inBody = Math.abs(relX) <= 0.85;
      }
    } else if (bodyType === "ghost") {
      const distGhost = Math.sqrt(relX * relX + relY * relY);
      if (relY < 0.5) {
        inBody = distGhost <= 1.0;
      } else {
        inBody = Math.abs(relX) <= 0.9 && (Math.floor(x + bodyWidth) % 2 === 0 || relY < 0.8);
      }
    }

    if (inBody && posX >= 0 && posX < size && posY >= 0 && posY < size) {
      grid[posY][posX] = { char: dnaObj.bodyChar, type: 'body' };
    }
  }
}

const isBodyChar = c => c && c.type === "body";

// Draw eyes
const eyeY = bodyStartY + 1;
if (isKid) {
  const eyeCount = 1 + Math.floor(random() * 3);
  if (eyeCount === 1) {
    for (let dy = 0; dy < 2; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (isBodyChar(grid[eyeY + dy][cx + dx])) {
          grid[eyeY + dy][cx + dx] = { char: ' ', type: 'empty' };
        }
      }
    }
    grid[eyeY][cx - 1] = { char: dnaObj.bodyChar, type: 'body' };
    grid[eyeY][cx] = { char: dnaObj.eyeChar, type: 'eye' };
    grid[eyeY][cx + 1] = { char: dnaObj.bodyChar, type: 'body' };
    grid[eyeY + 1][cx] = { char: dnaObj.bodyChar, type: 'body' };
  } else if (eyeCount === 2) {
    const eyeSpacing = 1;
    for (let dy = 0; dy < 2; dy++) {
      for (let dx = 0; dx < 2; dx++) {
        if (isBodyChar(grid[eyeY + dy][cx - eyeSpacing - 1 + dx])) {
          grid[eyeY + dy][cx - eyeSpacing - 1 + dx] = { char: ' ', type: 'empty' };
        }
        if (isBodyChar(grid[eyeY + dy][cx + eyeSpacing + dx])) {
          grid[eyeY + dy][cx + eyeSpacing + dx] = { char: ' ', type: 'empty' };
        }
      }
    }
    grid[eyeY][cx - eyeSpacing - 1] = { char: dnaObj.bodyChar, type: 'body' };
    grid[eyeY][cx - eyeSpacing] = { char: dnaObj.eyeChar, type: 'eye' };
    grid[eyeY + 1][cx - eyeSpacing - 1] = { char: dnaObj.bodyChar, type: 'body' };
    grid[eyeY + 1][cx - eyeSpacing] = { char: dnaObj.bodyChar, type: 'body' };
    grid[eyeY][cx + eyeSpacing] = { char: dnaObj.eyeChar, type: 'eye' };
    grid[eyeY][cx + eyeSpacing + 1] = { char: dnaObj.bodyChar, type: 'body' };
    grid[eyeY + 1][cx + eyeSpacing] = { char: dnaObj.bodyChar, type: 'body' };
    grid[eyeY + 1][cx + eyeSpacing + 1] = { char: dnaObj.bodyChar, type: 'body' };
  } else {
    for (let dx of [-2, 0, 2]) {
      if (isBodyChar(grid[eyeY][cx + dx])) grid[eyeY][cx + dx] = { char: ' ', type: 'empty' };
      grid[eyeY][cx + dx] = { char: dnaObj.eyeChar, type: 'eye' };
    }
  }
} else {
  const eyeCount = 1 + Math.floor(random() * 3);
  if (eyeCount === 1) {
    for (let dy = 0; dy < 3; dy++) {
      for (let dx = -2; dx <= 2; dx++) {
        if (isBodyChar(grid[eyeY + dy][cx + dx])) {
          grid[eyeY + dy][cx + dx] = { char: ' ', type: 'empty' };
        }
      }
    }
    for (let dx = -2; dx <= 2; dx++) {
      grid[eyeY][cx + dx] = { char: dnaObj.bodyChar, type: 'body' };
      grid[eyeY + 2][cx + dx] = { char: dnaObj.bodyChar, type: 'body' };
    }
    grid[eyeY + 1][cx - 2] = { char: dnaObj.bodyChar, type: 'body' };
    grid[eyeY + 1][cx - 1] = { char: dnaObj.eyeChar, type: 'eye' };
    grid[eyeY + 1][cx] = { char: dnaObj.eyeChar, type: 'eye' };
    grid[eyeY + 1][cx + 1] = { char: dnaObj.eyeChar, type: 'eye' };
    grid[eyeY + 1][cx + 2] = { char: dnaObj.bodyChar, type: 'body' };
  } else if (eyeCount === 2) {
    const blockSpacing = 2;
    for (let dy = 0; dy < 3; dy++) {
      for (let dx = 0; dx < 3; dx++) {
        if (isBodyChar(grid[eyeY + dy][cx - blockSpacing - 2 + dx])) {
          grid[eyeY + dy][cx - blockSpacing - 2 + dx] = { char: ' ', type: 'empty' };
        }
        if (isBodyChar(grid[eyeY + dy][cx + blockSpacing + dx])) {
          grid[eyeY + dy][cx + blockSpacing + dx] = { char: ' ', type: 'empty' };
        }
      }
    }
    for (let dy = 0; dy < 3; dy++) {
      for (let dx = 0; dx < 3; dx++) {
        const isCenter = dy === 1 && dx === 1;
        grid[eyeY + dy][cx - blockSpacing - 2 + dx] = { char: isCenter ? dnaObj.eyeChar : dnaObj.bodyChar, type: isCenter ? 'eye' : 'body' };
        grid[eyeY + dy][cx + blockSpacing + dx] = { char: isCenter ? dnaObj.eyeChar : dnaObj.bodyChar, type: isCenter ? 'eye' : 'body' };
      }
    }
  } else {
    for (let i = -3; i <= 3; i += 3) {
      for (let dy = 0; dy < 2; dy++) {
        if (isBodyChar(grid[eyeY + dy][cx + i])) grid[eyeY + dy][cx + i] = { char: ' ', type: 'empty' };
        if (isBodyChar(grid[eyeY + dy][cx + i - 1])) grid[eyeY + dy][cx + i - 1] = { char: ' ', type: 'empty' };
        grid[eyeY + dy][cx + i] = { char: dnaObj.eyeChar, type: 'eye' };
        grid[eyeY + dy][cx + i - 1] = { char: dnaObj.eyeChar, type: 'eye' };
      }
    }
  }
}

// Draw mouth
if (random() > 0.3) {
  const mouthY = eyeY + (isKid ? 2 : 3);
  if (mouthY < size && isBodyChar(grid[mouthY][cx])) {
    grid[mouthY][cx] = { char: "\u2500", type: 'mouth' };
    if (random() > 0.5 && isBodyChar(grid[mouthY][cx - 1])) {
      grid[mouthY][cx - 1] = { char: "\u2500", type: 'mouth' };
    }
    if (random() > 0.5 && isBodyChar(grid[mouthY][cx + 1])) {
      grid[mouthY][cx + 1] = { char: "\u2500", type: 'mouth' };
    }
  }
}

// Draw cigarette
if (dnaObj.hasCigarette) {
  const cigY = eyeY + (isKid ? 2 : 3);
  const cigChars = ["\u2248", "\u223c", "~"];
  const cigChar = cigChars[Math.floor(random() * cigChars.length)];
  const cigX = cx + (random() > 0.5 ? 3 : -3);
  if (cigX >= 0 && cigX < size && cigY >= 0 && cigY < size) {
    grid[cigY][cigX] = { char: cigChar, type: 'cigarette' };
    if (cigX + 1 < size) grid[cigY][cigX + 1] = { char: '\u2219', type: 'cigarette' };
  }
}

// Draw arms
const armCount = 1 + Math.floor(random() * 4);
const armLength = isKid ? (1 + Math.floor(random() * 2)) : (2 + Math.floor(random() * 4));
const armChar = dnaObj.armStyle === "block" ? "\u2588" : "\u2500";
for (let a = 0; a < armCount; a++) {
  const currentArmY = bodyStartY + 2 + a * (isKid ? 1 : 2);
  if (currentArmY >= bodyStartY + bodyHeight) break;
  let leftBodyEdge = cx, rightBodyEdge = cx;
  for (let x = cx; x >= 0; x--) {
    if (isBodyChar(grid[currentArmY][x])) {
      leftBodyEdge = x;
    } else {
      break;
    }
  }
  for (let x = cx; x < size; x++) {
    if (isBodyChar(grid[currentArmY][x])) {
      rightBodyEdge = x;
    } else {
      break;
    }
  }
  for (let i = 1; i <= armLength; i++) {
    if (leftBodyEdge - i >= 0) {
      grid[currentArmY][leftBodyEdge - i] = { char: armChar, type: 'arm' };
    }
    if (rightBodyEdge + i < size) {
      grid[currentArmY][rightBodyEdge + i] = { char: armChar, type: 'arm' };
    }
  }
}

// Draw legs
const legCount = 1 + Math.floor(random() * 4);
const legY = bodyStartY + bodyHeight;
const legLength = isKid ? (1 + Math.floor(random() * 2)) : (2 + Math.floor(random() * 3));
const legChar = dnaObj.legStyle === "block" ? "\u2588" : "\u2502";
const bodyBottomPositions = [];
for (let x = 0; x < size; x++) {
  if (grid[legY - 1] && isBodyChar(grid[legY - 1][x])) {
    bodyBottomPositions.push(x);
  }
}
const legPositions = [];
if (bodyBottomPositions.length > 0) {
  if (legCount === 1) {
    legPositions.push(bodyBottomPositions[Math.floor(bodyBottomPositions.length / 2)]);
  } else if (legCount === 2) {
    legPositions.push(bodyBottomPositions[Math.floor(bodyBottomPositions.length * 0.25)]);
    legPositions.push(bodyBottomPositions[Math.floor(bodyBottomPositions.length * 0.75)]);
  } else if (legCount === 3) {
    legPositions.push(bodyBottomPositions[0]);
    legPositions.push(bodyBottomPositions[Math.floor(bodyBottomPositions.length / 2)]);
    legPositions.push(bodyBottomPositions[bodyBottomPositions.length - 1]);
  } else {
    legPositions.push(bodyBottomPositions[0]);
    legPositions.push(bodyBottomPositions[Math.floor(bodyBottomPositions.length * 0.33)]);
    legPositions.push(bodyBottomPositions[Math.floor(bodyBottomPositions.length * 0.66)]);
    legPositions.push(bodyBottomPositions[bodyBottomPositions.length - 1]);
  }
}
for (let legX of legPositions) {
  if (legX >= 0 && legX < size) {
    for (let i = 0; i < legLength; i++) {
      if (legY + i < size) {
        grid[legY + i][legX] = { char: legChar, type: 'leg' };
      }
    }
  }
}

// Draw antennas
const antennaCount = 1 + Math.floor(random() * 4);
const antennaLength = isKid ? 1 : (1 + Math.floor(random() * 2));
const bodyTopPositions = [];
for (let x = 0; x < size; x++) {
  if (grid[bodyStartY] && isBodyChar(grid[bodyStartY][x])) {
    bodyTopPositions.push(x);
  }
}
const antennaPositions = [];
if (bodyTopPositions.length > 0) {
  if (antennaCount === 1) {
    antennaPositions.push(bodyTopPositions[Math.floor(bodyTopPositions.length / 2)]);
  } else if (antennaCount === 2) {
    antennaPositions.push(bodyTopPositions[Math.floor(bodyTopPositions.length * 0.25)]);
    antennaPositions.push(bodyTopPositions[Math.floor(bodyTopPositions.length * 0.75)]);
  } else if (antennaCount === 3) {
    antennaPositions.push(bodyTopPositions[0]);
    antennaPositions.push(bodyTopPositions[Math.floor(bodyTopPositions.length / 2)]);
    antennaPositions.push(bodyTopPositions[bodyTopPositions.length - 1]);
  } else {
    antennaPositions.push(bodyTopPositions[0]);
    antennaPositions.push(bodyTopPositions[Math.floor(bodyTopPositions.length * 0.33)]);
    antennaPositions.push(bodyTopPositions[Math.floor(bodyTopPositions.length * 0.66)]);
    antennaPositions.push(bodyTopPositions[bodyTopPositions.length - 1]);
  }
}
for (let antennaX of antennaPositions) {
  for (let i = 1; i <= antennaLength; i++) {
    const antennaY = bodyStartY - i;
    if (antennaY >= 0) {
      grid[antennaY][antennaX] = { char: i === antennaLength ? dnaObj.antennaTip : '\u2502', type: i === antennaLength ? 'antenna-tip' : 'antenna' };
    }
  }
}

// Draw hat
if (dnaObj.hatType && dnaObj.hatType !== "none") {
  const hatY = bodyStartY - antennaLength - 1;
  if (hatY >= 0) {
    if (dnaObj.hatType === "top") {
      for (let dx = -2; dx <= 2; dx++) {
        if (cx + dx >= 0 && cx + dx < size) {
          grid[hatY][cx + dx] = { char: "\u2580", type: 'hat' };
        }
      }
      if (hatY + 1 < size) {
        grid[hatY + 1][cx] = { char: "\u2588", type: 'hat' };
      }
    } else if (dnaObj.hatType === "flat") {
      for (let dx = -2; dx <= 2; dx++) {
        if (cx + dx >= 0 && cx + dx < size) {
          grid[hatY][cx + dx] = { char: "\u2550", type: 'hat' };
        }
      }
    } else if (dnaObj.hatType === "double") {
      for (let dx = -2; dx <= 2; dx++) {
        if (cx + dx >= 0 && cx + dx < size && hatY - 1 >= 0) {
          grid[hatY - 1][cx + dx] = { char: "\u2580", type: 'hat' };
          grid[hatY][cx + dx] = { char: "\u2584", type: 'hat' };
        }
      }
    } else if (dnaObj.hatType === "fancy") {
      if (cx - 2 >= 0 && cx + 2 < size) {
        grid[hatY][cx - 2] = { char: "\u2554", type: 'hat' };
        grid[hatY][cx - 1] = { char: "\u2550", type: 'hat' };
        grid[hatY][cx] = { char: "\u2550", type: 'hat' };
        grid[hatY][cx + 1] = { char: "\u2550", type: 'hat' };
        grid[hatY][cx + 2] = { char: "\u2557", type: 'hat' };
      }
    }
  }
}

// Calculate temperament for animation
const tempNames = ['calm', 'balanced', 'energetic', 'chaotic', 'glitchy', 'unstable'];
const tempWeights = [35, 30, 20, 10, 4, 1];
const tempSpeeds = [1.5, 2.5, 3.5, 5.0, 6.0, 7.0];
const tempGlitch = [0.02, 0.05, 0.12, 0.25, 0.40, 0.60];
const tempCorrupt = [0.0, 0.0, 0.03, 0.08, 0.15, 0.25];
const totalWeight = tempWeights.reduce((s, w) => s + w, 0);
let r = random() * totalWeight;
let tempIndex = 0;
for (let i = 0; i < tempWeights.length; i++) {
  r -= tempWeights[i];
  if (r <= 0) {
    tempIndex = i;
    break;
  }
}
const temperament = tempNames[tempIndex];
const speed = tempSpeeds[tempIndex];
const glitchChance = tempGlitch[tempIndex];
const charCorrupt = tempCorrupt[tempIndex];

// Generate SVG
const fontSize = size === 24 ? 20 : 16;
const charWidth = fontSize * 0.6;
const lineHeight = fontSize;
const viewBoxWidth = size * charWidth;
const viewBoxHeight = size * lineHeight;

let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${viewBoxWidth} ${viewBoxHeight}" width="${viewBoxWidth}" height="${viewBoxHeight}">`;

// Add CSS animations
svg += `<style>
  <![CDATA[
    text {
      font-family: 'Courier New', monospace;
      font-size: ${fontSize}px;
      fill: ${familyColor};
      text-anchor: start;
      dominant-baseline: text-before-edge;
    }

    /* Body bobbing animation */
    .body {
      animation: body-float 2s ease-in-out infinite;
    }
    @keyframes body-float {
      0%, 100% { transform: translateY(0px); }
      50% { transform: translateY(-2px); }
    }

    /* Eye blinking */
    .eye {
      animation: eye-blink 4s ease-in-out infinite;
    }
    @keyframes eye-blink {
      0%, 47%, 53%, 100% { opacity: 1; }
      50% { opacity: 0; }
    }

    /* Arm waving */
    .arm {
      animation: arm-wave 2s ease-in-out infinite;
      transform-origin: center;
    }
    @keyframes arm-wave {
      0%, 100% { transform: translateY(0px); }
      50% { transform: translateY(-3px); }
    }

    /* Leg movement */
    .leg {
      animation: leg-move 1.5s ease-in-out infinite;
    }
    @keyframes leg-move {
      0%, 100% { transform: translateY(0px); }
      50% { transform: translateY(2px); }
    }

    /* Antenna sway */
    .antenna, .antenna-tip {
      animation: antenna-sway 3s ease-in-out infinite;
      transform-origin: bottom center;
    }
    @keyframes antenna-sway {
      0%, 100% { transform: translateX(0px); }
      50% { transform: translateX(2px); }
    }

    /* Temperament-specific animations */
    ${temperament === 'energetic' || temperament === 'chaotic' || temperament === 'glitchy' || temperament === 'unstable' ? `
    .eye {
      animation: eye-blink 4s ease-in-out infinite, eye-wiggle 1s ease-in-out infinite;
    }
    @keyframes eye-wiggle {
      0%, 100% { transform: translateX(0px); }
      50% { transform: translateX(1.5px); }
    }

    .arm {
      animation: arm-wave 2s ease-in-out infinite, arm-swing 1.5s ease-in-out infinite;
    }
    @keyframes arm-swing {
      0%, 100% { transform: translateX(0px); }
      50% { transform: translateX(2px); }
    }
    ` : ''}

    ${temperament === 'chaotic' || temperament === 'glitchy' || temperament === 'unstable' ? `
    @keyframes glitch {
      0%, 100% { transform: translate(0, 0); }
      20% { transform: translate(-2px, 1px); }
      40% { transform: translate(1px, -1px); }
      60% { transform: translate(2px, 1px); }
      80% { transform: translate(-1px, -2px); }
    }
    .body, .eye, .arm, .leg, .antenna, .antenna-tip, .mouth {
      animation-name: glitch;
      animation-duration: ${speed}s;
      animation-iteration-count: infinite;
      animation-timing-function: linear;
    }
    ` : ''}

    ${temperament === 'unstable' ? `
    @keyframes unstable-scale {
      0%, 100% { transform: scale(1); }
      50% { transform: scale(0.95); }
    }
    text {
      animation: unstable-scale 0.8s ease-in-out infinite;
    }
    ` : ''}
  ]]>
</style>`;

// Render grid to SVG text elements
for (let y = 0; y < size; y++) {
  for (let x = 0; x < size; x++) {
    const cell = grid[y][x];
    if (!cell || cell.char === ' ') continue;

    const posX = x * charWidth;
    const posY = y * lineHeight;
    const escapedChar = cell.char
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');

    // Add unique delay based on position for more organic animation
    const delay = (x + y) * 0.05;
    const style = `animation-delay: ${delay}s;`;

    svg += `<text x="${posX}" y="${posY}" class="${cell.type}" style="${style}">${escapedChar}</text>`;
  }
}

svg += `</svg>`;

// Output the SVG
document.body.innerHTML = svg;
